SELECT r.response_overflow, r.message_id, r.op_id, r.attempt, r.tool_name, r.tool_kind, r.status, r.cost, r.request_payload_id, r.response_payload_id, r.turn_id, r.request_hash, r.error_code, r.error_message, r.retriable, r.started_at, r.completed_at, r.latency_ms, r.trace_id, r.span_id, r.run_id, r.iteration FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete, 0 AS response_overflow FROM tool_call c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)